import React, { useState, useEffect } from "react";
import {
  FaUser,
  FaBell,
  FaLock,
  FaPalette,
  FaShieldAlt,
  FaSignOutAlt,
  FaSave,
} from "react-icons/fa";
import Sidebar from "../../components/Sidebar/Sidebar";
import "./Settings.css";
import { API_URL } from "../../config/config";
import { useTheme } from "../../context/ThemeContext";
import { useNotificationSettings } from "../../context/NotificationSettingsContext";

const Settings = () => {
  const [activeTab, setActiveTab] = useState("profile");
  const [isLoading, setIsLoading] = useState(true);
  const [userData, setUserData] = useState(null);
  const [error, setError] = useState(null);
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    bio: "",
    status: "", // Déjà défini comme 'online' par défaut
  });
  const [avatarPreview, setAvatarPreview] = useState(null);
  const [avatarFile, setAvatarFile] = useState(null);
  // Nouvel état pour suivre si des modifications ont été effectuées
  const [hasChanges, setHasChanges] = useState(false);
  // Notification settings
  const { notificationSettings, updateNotificationSettings } =
    useNotificationSettings();
  const [notifications, setNotifications] = useState(notificationSettings);

  // Appearance settings
  const { theme, setTheme } = useTheme(); // Utilise le contexte pour le thème

  // Privacy settings
  const [privacy, setPrivacy] = useState({
    onlineStatus: "all",
    messageRequests: "all",
  });

  // État pour le modal de changement de mot de passe
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [oldPassword, setOldPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [passwordError, setPasswordError] = useState("");
  const [passwordSuccess, setPasswordSuccess] = useState("");
  const [isChangingPassword, setIsChangingPassword] = useState(false);

  // Fetch user data
  useEffect(() => {
    const fetchUserData = async () => {
      try {
        setIsLoading(true);
        const token = localStorage.getItem("token");

        if (!token) {
          throw new Error("No authentication token found");
        }

        const response = await fetch(`${API_URL}/api/users/profile`, {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });

        if (!response.ok) {
          throw new Error("Failed to fetch user data");
        }

        const data = await response.json();

        // Vérifier que le statut est valide, sinon utiliser 'online' comme défaut
        const validStatuses = ["online", "away", "dnd", "invisible"];
        const defaultStatus = "online";
        const userStatus = validStatuses.includes(data.status)
          ? data.status
          : defaultStatus;

        setUserData(data);
        setFormData({
          name: data.nom || "",
          email: data.email || "",
          bio: data.bio || "",
          status: userStatus, // Utiliser le statut validé
        });

        if (data.photo_url) {
          setAvatarPreview(data.photo_url);
        }

        // You could also fetch actual settings from the API here
      } catch (err) {
        // En cas d'erreur, s'assurer que le statut par défaut est 'online'
        setFormData((prevState) => ({
          ...prevState,
          status: "online",
        }));
        console.error("Error fetching user data:", err);
        setError(err.message);
      } finally {
        setIsLoading(false);
      }
    };

    fetchUserData();
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
    setHasChanges(true);
  };

  const handleAvatarChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    setAvatarFile(file);
    const reader = new FileReader();
    reader.onload = () => {
      setAvatarPreview(reader.result);
    };
    reader.readAsDataURL(file);
    setHasChanges(true);
  };
  const handleNotificationChange = (setting) => {
    const updatedSettings = {
      ...notifications,
      [setting]: !notifications[setting],
    };
    setNotifications(updatedSettings);
    updateNotificationSettings(updatedSettings);
    setHasChanges(true);
  };

  const handlePrivacyChange = (setting, value) => {
    setPrivacy({
      ...privacy,
      [setting]: value,
    });
    setHasChanges(true);
  };

  // Fonction pour réinitialiser l'état des modifications après sauvegarde
  const resetChangesState = () => {
    setHasChanges(false);
  };

  const handleSubmit = async (e) => {
    if (e) e.preventDefault();
    setIsLoading(true);

    try {
      const token = localStorage.getItem("token");
      const formDataToSend = new FormData();

      formDataToSend.append("nom", formData.name);
      formDataToSend.append("bio", formData.bio);

      // Convertir le statut en identifiant numérique correspondant
      const statusMap = {
        online: 1, // En ligne
        away: 2, // Absent
        dnd: 3, // Ne pas déranger
        invisible: 4, // Invisible
      };

      // Obtenir l'ID du statut ou utiliser 1 (en ligne) par défaut
      const statusId = statusMap[formData.status] || 1;
      console.log("Envoi du statut:", { status: formData.status, statusId });

      // S'assurer que le statut est envoyé comme un nombre, pas une chaîne
      formDataToSend.append("fk_statut", statusId.toString());

      // Log pour débogage - vérifier ce qui est réellement envoyé
      for (let pair of formDataToSend.entries()) {
        console.log(pair[0] + ": " + pair[1]);
      }

      if (avatarFile) {
        formDataToSend.append("avatar", avatarFile);
      }

      // S'assurer que nous utilisons l'URL correcte
      const response = await fetch(`${API_URL}/api/users/profile`, {
        method: "PUT",
        headers: {
          Authorization: `Bearer ${token}`,
        },
        body: formDataToSend,
      });

      // Analyser la réponse même en cas d'erreur pour le débogage
      const responseData = await response.json();
      console.log("Réponse du serveur:", responseData);

      if (!response.ok) {
        throw new Error(responseData.message || "Failed to update profile");
      }

      // Mise à jour du state local avec les données renvoyées
      if (responseData.user) {
        setFormData((prev) => ({
          ...prev,
          name: responseData.user.nom || prev.name,
          bio: responseData.user.bio || prev.bio,
        }));

        // Mettre à jour l'avatar si nécessaire
        if (responseData.user.photo_url) {
          setAvatarPreview(responseData.user.photo_url);
        }
      }

      alert("Profile updated successfully");
      resetChangesState();
    } catch (err) {
      console.error("Error updating profile:", err);
      setError(err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSaveSettings = (settingType) => {
    // Simuler la sauvegarde des paramètres
    console.log(
      `Saving ${settingType} settings:`,
      settingType === "notifications"
        ? notifications
        : settingType === "privacy"
        ? privacy
        : settingType === "appearance"
        ? { theme }
        : null
    );
    alert(`${settingType} settings saved!`);
    resetChangesState();
  };
  // Fonction pour gérer l'action du bouton flottant en fonction de l'onglet actif
  const handleFloatingButtonAction = () => {
    switch (activeTab) {
      case "profile":
        handleSubmit();
        break;
      case "notifications":
        handleSaveSettings("notifications");
        break;
      case "privacy":
        handleSaveSettings("privacy");
        break;
      case "appearance":
        handleSaveSettings("appearance");
        break;
      default:
        break;
    }
  };

  // Réinitialiser l'état des modifications lors du changement d'onglet
  const handleTabChange = (tab) => {
    setActiveTab(tab);
    setHasChanges(false);
  };

  const handleLogout = () => {
    localStorage.removeItem("token");
    window.location.href = "/login";
  };

  const handleDeleteAccount = () => {
    // Show confirmation dialog
    const confirmed = window.confirm(
      "Êtes-vous sûr de vouloir supprimer votre compte? Cette action est irréversible et toutes vos données seront perdues."
    );

    if (confirmed) {
      // Get user ID from token
      const token = localStorage.getItem("token");
      if (!token) {
        console.error("No token found, cannot delete account");
        return;
      }

      // Extract user ID from token payload
      const tokenPayload = JSON.parse(atob(token.split(".")[1]));
      const userId = tokenPayload.id;

      // Call API to delete account
      fetch(`${API_URL}/api/users/${userId}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      })
        .then((response) => {
          if (!response.ok) {
            throw new Error("Failed to delete account");
          }
          return response.json();
        })
        .then((data) => {
          console.log("Account deleted successfully:", data);
          alert(
            "Votre compte a été supprimé avec succès. Vous allez être déconnecté."
          );
          // Log out after successful deletion
          handleLogout();
        })
        .catch((error) => {
          console.error("Error deleting account:", error);
          alert(
            "Une erreur est survenue lors de la suppression de votre compte. Veuillez réessayer."
          );
        });
    }
  };

  // Handler pour le changement de mot de passe
  const handleChangePassword = async (e) => {
    e.preventDefault();
    setPasswordError("");
    setPasswordSuccess("");
    if (!oldPassword || !newPassword || !confirmPassword) {
      setPasswordError("Tous les champs sont requis.");
      return;
    }
    if (newPassword.length < 8) {
      setPasswordError(
        "Le nouveau mot de passe doit contenir au moins 8 caractères."
      );
      return;
    }
    if (newPassword !== confirmPassword) {
      setPasswordError("Les mots de passe ne correspondent pas.");
      return;
    }
    setIsChangingPassword(true);
    try {
      const token = localStorage.getItem("token");
      const response = await fetch(`${API_URL}/api/users/change-password`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ oldPassword, newPassword }),
      });
      const data = await response.json();
      if (!response.ok) {
        setPasswordError(
          data.message || "Erreur lors du changement de mot de passe."
        );
      } else {
        setPasswordSuccess("Mot de passe changé avec succès.");
        setOldPassword("");
        setNewPassword("");
        setConfirmPassword("");
        setTimeout(() => setShowPasswordModal(false), 1500);
      }
    } catch (err) {
      setPasswordError("Erreur de connexion au serveur.");
    } finally {
      setIsChangingPassword(false);
    }
  };

  if (isLoading && !userData) {
    return (
      <div className="app-layout">
        <Sidebar />
        <div className="settings-container loading-container">
          <div className="loading-indicator">Chargement des paramètres...</div>
        </div>
      </div>
    );
  }

  return (
    <div className="app-layout">
      <Sidebar />
      <div className="settings-container">
        <div className="glow-circle-right top-right"></div>
        <div className="glow-circle-left bottom-left"></div>

        <div className="settings-header">
          <h1>Paramètres</h1>
          <p>Personnalisez votre expérience SUPCHAT</p>
        </div>

        <div className="settings-layout">
          <div className="settings-sidebar">
            <button
              className={`settings-tab ${
                activeTab === "profile" ? "active" : ""
              }`}
              onClick={() => handleTabChange("profile")}
            >
              <FaUser className="tab-icon" />
              <span>Profil</span>
            </button>
            <button
              className={`settings-tab ${
                activeTab === "notifications" ? "active" : ""
              }`}
              onClick={() => handleTabChange("notifications")}
            >
              <FaBell className="tab-icon" />
              <span>Notifications</span>
            </button>
            <button
              className={`settings-tab ${
                activeTab === "privacy" ? "active" : ""
              }`}
              onClick={() => handleTabChange("privacy")}
            >
              <FaLock className="tab-icon" />
              <span>Confidentialité</span>
            </button>
            <button
              className={`settings-tab ${
                activeTab === "appearance" ? "active" : ""
              }`}
              onClick={() => handleTabChange("appearance")}
            >
              <FaPalette className="tab-icon" />
              <span>Apparence</span>
            </button>
            <button
              className={`settings-tab ${
                activeTab === "security" ? "active" : ""
              }`}
              onClick={() => handleTabChange("security")}
            >
              <FaShieldAlt className="tab-icon" />
              <span>Sécurité</span>
            </button>
            <button
              className={`settings-tab danger ${
                activeTab === "logout" ? "active" : ""
              }`}
              onClick={handleLogout}
            >
              <FaSignOutAlt className="tab-icon" />
              <span>Déconnexion</span>
            </button>
          </div>

          <div className="settings-content">
            {/* Profile Settings */}
            {activeTab === "profile" && (
              <div className="settings-section">
                <h2>Mon Profil</h2>
                {error && <div className="error-message">{error}</div>}

                <form onSubmit={handleSubmit} className="settings-form">
                  {/* Avatar et présentation */}
                  <div className="profile-header">
                    <div className="avatar-upload">
                      <div className="avatar-preview">
                        {avatarPreview ? (
                          <img src={avatarPreview} alt="Avatar preview" />
                        ) : (
                          <div className="avatar-placeholder">
                            {formData.name
                              ? formData.name[0].toUpperCase()
                              : "?"}
                          </div>
                        )}
                        <div className="avatar-overlay">
                          <label
                            htmlFor="avatar-input"
                            className="change-avatar-btn"
                          >
                            Changer
                          </label>
                          <input
                            type="file"
                            id="avatar-input"
                            accept="image/*"
                            onChange={handleAvatarChange}
                            style={{ display: "none" }}
                          />
                        </div>
                      </div>
                    </div>

                    <div className="profile-user-info">
                      <h3>{formData.name || "Votre nom"}</h3>
                      <p className="user-email">{formData.email}</p>

                      {/* Nouveau sélecteur de statut moderne */}
                      <div className="status-selector">
                        <div className="status-dropdown">
                          <div className="current-status">
                            <span
                              className={`status-dot status-${formData.status}`}
                            ></span>
                            <span className="status-text">
                              {formData.status === "online" && "En ligne"}
                              {formData.status === "away" && "Absent"}
                              {formData.status === "dnd" && "Ne pas déranger"}
                              {formData.status === "invisible" && "Invisible"}
                            </span>
                            <div className="status-options">
                              <div
                                className="status-option"
                                onClick={() =>
                                  handleInputChange({
                                    target: { name: "status", value: "online" },
                                  })
                                }
                              >
                                <span className="status-dot status-online"></span>
                                <span>En ligne</span>
                              </div>
                              <div
                                className="status-option"
                                onClick={() =>
                                  handleInputChange({
                                    target: { name: "status", value: "away" },
                                  })
                                }
                              >
                                <span className="status-dot status-away"></span>
                                <span>Absent</span>
                              </div>
                              <div
                                className="status-option"
                                onClick={() =>
                                  handleInputChange({
                                    target: { name: "status", value: "dnd" },
                                  })
                                }
                              >
                                <span className="status-dot status-dnd"></span>
                                <span>Ne pas déranger</span>
                              </div>
                              <div
                                className="status-option"
                                onClick={() =>
                                  handleInputChange({
                                    target: {
                                      name: "status",
                                      value: "invisible",
                                    },
                                  })
                                }
                              >
                                <span className="status-dot status-invisible"></span>
                                <span>Invisible</span>
                              </div>
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>

                  <div className="settings-separator">
                    <span>Informations personnelles</span>
                  </div>

                  <div className="profile-section">
                    <div className="form-group">
                      <label htmlFor="name">Nom d'affichage</label>
                      <input
                        type="text"
                        id="name"
                        name="name"
                        value={formData.name}
                        onChange={handleInputChange}
                        className="form-input"
                      />
                      <small>
                        Ce nom sera visible par tous les utilisateurs
                      </small>
                    </div>

                    <div className="form-group">
                      <label htmlFor="email">Adresse e-mail</label>
                      <input
                        type="email"
                        id="email"
                        name="email"
                        value={formData.email}
                        readOnly
                        className="form-input readonly"
                      />
                      <small>L'adresse e-mail ne peut pas être modifiée</small>
                    </div>
                  </div>

                  <div className="settings-separator">
                    <span>Personnalisation</span>
                  </div>

                  <div className="profile-section">
                    <div className="form-group">
                      <label htmlFor="bio">Bio</label>
                      <textarea
                        id="bio"
                        name="bio"
                        value={formData.bio}
                        onChange={handleInputChange}
                        rows={4}
                        className="form-textarea"
                        placeholder="Partagez quelque chose à propos de vous..."
                      />
                      <small>Maximum 200 caractères</small>
                    </div>
                  </div>

                  {/* Suppression de la section Préférences qui contenait le statut */}
                </form>
              </div>
            )}

            {/* Notifications Settings */}
            {activeTab === "notifications" && (
              <div className="settings-section">
                <h2>Paramètres de notification</h2>

                <div className="settings-group">
                  <div className="settings-item">
                    <div className="setting-info">
                      <h3>Notifications de messages</h3>
                      <p>
                        Recevez des notifications lorsque vous recevez des
                        messages
                      </p>
                    </div>
                    <div className="setting-control">
                      <label className="switch">
                        <input
                          type="checkbox"
                          checked={notifications.messages}
                          onChange={() => handleNotificationChange("messages")}
                        />
                        <span className="slider"></span>
                      </label>
                    </div>
                  </div>
                  <div className="settings-item">
                    <div className="setting-info">
                      <h3>Notifications de mentions</h3>
                      <p>
                        Recevez des notifications lorsque vous êtes mentionné
                      </p>
                    </div>
                    <div className="setting-control">
                      <label className="switch">
                        <input
                          type="checkbox"
                          checked={notifications.mentions}
                          onChange={() => handleNotificationChange("mentions")}
                        />
                        <span className="slider"></span>
                      </label>
                    </div>
                  </div>{" "}
                  <div className="settings-item">
                    <div className="setting-info">
                      <h3>Sons de notification</h3>
                      <p>Jouer un son lorsque vous recevez une notification</p>
                      {notifications.sounds && (
                        <button
                          onClick={() => {
                            // Tester le son directement                            // Utiliser notre utilitaire pour tester le son
                            import("../../assets/sounds/soundUtils")
                              .then((module) => {
                                module
                                  .testNotificationSound()
                                  .then((success) => {
                                    if (success) {
                                      console.log(
                                        "Test de son réussi via l'utilitaire"
                                      );
                                    } else {
                                      console.warn("Le test de son a échoué");
                                    }
                                  });
                              })
                              .catch((error) =>
                                console.error(
                                  "Erreur lors de l'import de l'utilitaire de son:",
                                  error
                                )
                              );
                          }}
                          style={{
                            marginTop: "5px",
                            padding: "3px 10px",
                            fontSize: "12px",
                            background: "#333",
                            color: "#fff",
                            border: "none",
                            borderRadius: "4px",
                            cursor: "pointer",
                          }}
                        >
                          Tester le son
                        </button>
                      )}
                    </div>
                    <div className="setting-control">
                      <label className="switch">
                        <input
                          type="checkbox"
                          checked={notifications.sounds}
                          onChange={() => handleNotificationChange("sounds")}
                        />
                        <span className="slider"></span>
                      </label>
                    </div>
                  </div>
                  <div className="settings-item">
                    <div className="setting-info">
                      <h3>Notifications par e-mail</h3>
                      <p>
                        Recevez des notifications par e-mail lorsque vous êtes
                        hors ligne
                      </p>
                    </div>
                    <div className="setting-control">
                      <label className="switch">
                        <input
                          type="checkbox"
                          checked={notifications.email}
                          onChange={() => handleNotificationChange("email")}
                        />
                        <span className="slider"></span>
                      </label>
                    </div>
                  </div>
                  <div className="settings-item">
                    <div className="setting-info">
                      <h3>Notifications sur ordinateur</h3>
                      <p>Afficher les notifications sur votre bureau</p>
                    </div>
                    <div className="setting-control">
                      <label className="switch">
                        <input
                          type="checkbox"
                          checked={notifications.desktop}
                          onChange={() => handleNotificationChange("desktop")}
                        />
                        <span className="slider"></span>
                      </label>
                    </div>
                  </div>
                </div>

                {/* Suppression du bouton d'enregistrement statique */}
              </div>
            )}

            {/* Privacy Settings */}
            {activeTab === "privacy" && (
              <div className="settings-section">
                <h2>Paramètres de confidentialité</h2>
                <div className="settings-group">
                  <div className="settings-item">
                    <div className="setting-info">
                      <h3>Qui peut voir mon statut en ligne</h3>
                    </div>
                    <div className="setting-control">
                      <select
                        className="form-select"
                        value={privacy.onlineStatus}
                        onChange={(e) =>
                          handlePrivacyChange("onlineStatus", e.target.value)
                        }
                      >
                        <option value="all">Tout le monde</option>
                        <option value="friends">Seulement mes amis</option>
                        <option value="none">Personne</option>
                      </select>
                    </div>
                  </div>                  {/* Bouton d'accès aux CGU */}                  <div className="settings-item">
                    <div className="setting-info">
                      <h3>Conditions Générales d'Utilisation</h3>
                      <p>Consultez les CGU de SUPCHAT pour connaître vos droits et obligations.</p>
                    </div>
                    <div className="setting-control">
                      <a href="/cgu" target="_blank" rel="noopener noreferrer" className="btn-secondary" style={{ display: 'inline-block', textDecoration: 'none' }}>Voir les CGU</a>
                    </div>
                  </div>

                  {/* Suppression du paramètre 'Accusés de lecture' ici */}
                  {/* Suppression du paramètre 'Qui peut m'envoyer des demandes de messages' déjà effectuée */}
                </div>

                {/* Suppression du bouton d'enregistrement statique */}
              </div>
            )}

            {/* Appearance Settings */}
            {activeTab === "appearance" && (
              <div className="settings-section">
                <h2>Paramètres d'apparence</h2>

                <div className="settings-group">
                  <div className="theme-selector">
                    <h3>Thème</h3>
                    <div className="theme-options">
                      <div
                        className={`theme-option ${
                          theme === "dark" ? "active" : ""
                        }`}
                        onClick={() => setTheme("dark")}
                      >
                        <div className="theme-preview dark-theme"></div>
                        <span>Sombre</span>
                      </div>
                      <div
                        className={`theme-option ${
                          theme === "light" ? "active" : ""
                        }`}
                        onClick={() => setTheme("light")}
                      >
                        <div className="theme-preview light-theme"></div>
                        <span>Clair</span>
                      </div>
                      <div
                        className={`theme-option ${
                          theme === "system" ? "active" : ""
                        }`}
                        onClick={() => setTheme("system")}
                      >
                        <div className="theme-preview system-theme"></div>
                        <span>Système</span>
                      </div>
                    </div>
                  </div>
                </div>

                {/* Suppression du bouton d'enregistrement statique */}
              </div>
            )}

            {/* Security Settings */}
            {activeTab === "security" && (
              <div className="settings-section">
                <h2>Paramètres de sécurité</h2>

                <div className="settings-group">
                  <div className="security-option">
                    <h3>Changer de mot de passe</h3>
                    <p>
                      Mettez à jour votre mot de passe pour sécuriser votre
                      compte
                    </p>
                    <button
                      className="btn-secondary"
                      onClick={() => setShowPasswordModal(true)}
                    >
                      Changer de mot de passe
                    </button>
                  </div>

                  <div className="security-option danger-zone">
                    <h3>Supprimer mon compte</h3>
                    <p>
                      Cette action est irréversible et supprimera toutes vos
                      données
                    </p>
                    <button
                      className="btn-danger"
                      onClick={handleDeleteAccount}
                    >
                      Supprimer mon compte
                    </button>
                  </div>

                  <div className="security-option rgpd-export">
                    <h3>Exporter mes données RGPD</h3>
                    <p>
                      Téléchargez toutes vos données personnelles au format JSON
                      conformément au RGPD.
                    </p>
                    <button
                      className="btn-secondary"
                      onClick={async () => {
                        const token = localStorage.getItem("token");
                        if (!token) {
                          alert(
                            "Vous devez être connecté pour exporter vos données."
                          );
                          return;
                        }
                        try {
                          const response = await fetch(
                            `${API_URL}/api/users/rgpd-export`,
                            {
                              headers: { Authorization: `Bearer ${token}` },
                            }
                          );
                          if (!response.ok)
                            throw new Error("Erreur lors de l'export RGPD");
                          const blob = await response.blob();
                          const url = window.URL.createObjectURL(blob);
                          const a = document.createElement("a");
                          a.href = url;
                          a.download = "mes_donnees_rgpd.json";
                          document.body.appendChild(a);
                          a.click();
                          a.remove();
                          window.URL.revokeObjectURL(url);
                        } catch (err) {
                          alert(
                            "Erreur lors de l'export RGPD : " + err.message
                          );
                        }
                      }}
                    >
                      Exporter mes données RGPD
                    </button>
                  </div>
                </div>

                {/* Modal de changement de mot de passe */}
                {showPasswordModal && (
                  <div
                    className="modal-overlay"
                    onClick={() => setShowPasswordModal(false)}
                  >
                    <div
                      className="modal-content"
                      onClick={(e) => e.stopPropagation()}
                    >
                      <h2>Changer de mot de passe</h2>
                      <form onSubmit={handleChangePassword}>
                        <div className="form-group">
                          <label>Ancien mot de passe</label>
                          <input
                            type="password"
                            value={oldPassword}
                            onChange={(e) => setOldPassword(e.target.value)}
                            autoFocus
                            required
                          />
                        </div>
                        <div className="form-group">
                          <label>Nouveau mot de passe</label>
                          <input
                            type="password"
                            value={newPassword}
                            onChange={(e) => setNewPassword(e.target.value)}
                            required
                          />
                        </div>
                        <div className="form-group">
                          <label>Confirmer le nouveau mot de passe</label>
                          <input
                            type="password"
                            value={confirmPassword}
                            onChange={(e) => setConfirmPassword(e.target.value)}
                            required
                          />
                        </div>
                        {passwordError && (
                          <div className="error-message">{passwordError}</div>
                        )}
                        {passwordSuccess && (
                          <div className="success-message">
                            {passwordSuccess}
                          </div>
                        )}
                        <div className="modal-actions">
                          <button
                            type="button"
                            className="cancel-btn"
                            onClick={() => setShowPasswordModal(false)}
                          >
                            Annuler
                          </button>
                          <button
                            type="submit"
                            className="create-btn"
                            disabled={isChangingPassword}
                          >
                            {isChangingPassword
                              ? "Changement..."
                              : "Changer le mot de passe"}
                          </button>
                        </div>
                      </form>
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>

        {/* Bouton d'enregistrement flottant */}
        {hasChanges && activeTab !== "security" && (
          <div className="floating-save-button">
            <button
              className="btn-floating"
              onClick={handleFloatingButtonAction}
              disabled={isLoading}
            >
              <FaSave className="floating-icon" />
              <span>
                {isLoading
                  ? "Enregistrement..."
                  : "Enregistrer les modifications"}
              </span>
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default Settings;
